mapper.select:
SELECT T99.* FROM ( SELECT /* 서비스사업 기본내역 */ T21.BIZ_YR AS BIZ_YR -- 사업연도 , T21.SRVC_BIZ_NO AS SRVC_BIZ_NO -- 서비스사업번호 , T21.SRVC_BIZ_NM AS SRVC_BIZ_NM -- 서비스사업명 , T21.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD -- 단위업무구분코드 , T21.BIZ_CL_SE_CD AS BIZ_CL_SE_CD -- 사업분류구분코드 , T21.BGT_AMT AS BGT_AMT -- 예산금액 , T21.USE_YN AS USE_YN -- 사용여부 , T21.FRST_RGTR_ID AS FRST_RGTR_ID -- 최초등록자아이디 , T21.FRST_REG_DT AS FRST_REG_DT -- 최초등록일시 , T21.LAST_MDFR_ID AS LAST_MDFR_ID -- 최종수정자아이디 , T21.LAST_MDFCN_DT AS LAST_MDFCN_DT -- 최종수정일시 , ROWNUM AS SEQ FROM SDA400 T21 /* 서비스사업 */
WHERE 1 = 1
AND T21.BIZ_YR = #{BIZ_YR} -- 사업연도
) T99 WHERE 1 = 1
AND T99.SEQ >= #{START_IDX} AND T99.SEQ <= #{LAST_IDX}
ORDER BY T99.USE_YN DESC, T99.LAST_MDFCN_DT DESC

SELECT /* 실행서비스사업 목록조회 */ T1.EXCN_SRVC_BIZ_CL_NO /* 실행서비스사업분류번호 */ , T1.UNT_TASKWK_SE_CD /* 단위업무구분코드 */ , T1.SRVC_BIZ_NM /* 서비스사업명 */ , T1.BIZ_YR /* 사업연도 */ , T1.BIZ_CL_SE_CD /* 사업분류구분코드 */ , T1.BGT_AMT /* 예산금액 */ , T1.FRST_REG_DT /* 최초등록일시 */ , T1.USE_YN /* 사용여부 */ FROM SDA430 T1 /* 실행서비스사업 */ WHERE 1=1
AND T1.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND T1.BIZ_YR = #{BIZ_YR}
AND T1.BIZ_CL_SE_CD = #{BIZ_CL_SE_CD}
AND T1.SRVC_BIZ_NM LIKE '%'||#{SRVC_BIZ_NM}||'%'
ORDER BY T1.USE_YN DESC, T1.LAST_MDFCN_DT DESC

SELECT /* 실행서비스세부사업 목록조회 */ EXCN_SRVC_BIZ_CL_NO , EXCN_SRVC_DETAIA_BIZ_NO , EXCN_SRVC_DETAIA_BIZ_NM , BGT_EXCN_AMT , BIZ_BGNG_YMD , BIZ_END_YMD , EXCN_SRVC_DETAIA_BIZ_CL_SE_CD , USE_YN , CTPV_CD , SGG_CD , INST_NO , INST_NO_CN
, (SELECT LISTAGG(INST_NM, ', ') WITHIN GROUP(ORDER BY INST_NM) FROM SAA000 A WHERE A.INST_NO IN (SELECT REGEXP_SUBSTR(T1.INST_NO_CN, '[^,]+', 1,ROWNUM) FROM DUAL CONNECT BY ROWNUM < LENGTH(REGEXP_SUBSTR(T1.INST_NO_CN, '[^,]+')) + 1) AND DEL_YN = 'N') AS INST_NO_NM /* 기관명 목록 */
, FRST_REG_DT FROM SDA440 T1 /* 실행서비스세부사업 */ WHERE EXCN_SRVC_BIZ_CL_NO = #{EXCN_SRVC_BIZ_CL_NO}

mapper.delete:
DELETE /* isry.itgcm.crtrinfo.resrce.SrvcBizMapper.deleteExecSrvcDetaiaBiz(실행서비스세부사업 삭제) */
  FROM SDA440 /* 실행서비스세부사업 */
 WHERE EXCN_SRVC_BIZ_CL_NO      = #{EXCN_SRVC_BIZ_CL_NO}
   AND EXCN_SRVC_DETAIA_BIZ_NO  = #{EXCN_SRVC_DETAIA_BIZ_NO}

mapper.select:
SELECT A.BIZ_YR , A.BIZ_CL_SE_CD , A.EXCN_SRVC_BIZ_CL_NO , A.SRVC_BIZ_NM , B.EXCN_SRVC_DETAIA_BIZ_NO , B.EXCN_SRVC_DETAIA_BIZ_NM , B.EXCN_SRVC_DETAIA_BIZ_CL_SE_CD , B.BIZ_BGNG_YMD , B.BIZ_END_YMD , B.BGT_EXCN_AMT FROM SDA430 A, SDA440 B WHERE A.EXCN_SRVC_BIZ_CL_NO = B.EXCN_SRVC_BIZ_CL_NO AND 1 = CASE WHEN B.INST_NO_CN IS NULL THEN 1 ELSE (CASE WHEN B.INST_NO_CN LIKE '%'||#{INST_NO}||'%' THEN 1 ELSE 2 END) END AND (SELECT SGG_CD FROM SAA000 WHERE INST_NO = #{INST_NO}) = CASE WHEN B.SGG_CD IS NULL THEN (SELECT SGG_CD FROM SAA000 WHERE INST_NO = #{INST_NO}) ELSE B.SGG_CD END AND (SELECT CTPV_CD FROM SAA000 WHERE INST_NO = #{INST_NO}) = CASE WHEN B.CTPV_CD IS NULL THEN (SELECT CTPV_CD FROM SAA000 WHERE INST_NO = #{INST_NO}) ELSE B.CTPV_CD END
AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND A.BIZ_YR = #{BIZ_YR}
AND A.BIZ_CL_SE_CD = #{BIZ_CL_SE_CD}
AND A.SRVC_BIZ_NM LIKE '%'||#{SRVC_BIZ_NM}||'%'
AND B.EXCN_SRVC_DETAIA_BIZ_NM LIKE '%'||#{EXCN_SRVC_DETAIA_BIZ_NM}||'%'
AND B.EXCN_SRVC_DETAIA_BIZ_CL_SE_CD = #{EXCN_SRVC_DETAIA_BIZ_CL_SE_CD}
AND #{BIZ_YMD} BETWEEN B.BIZ_BGNG_YMD AND B.BIZ_END_YMD
AND B.BIZ_END_YMD >= TO_CHAR(SYSDATE,'YYYYMMDD')
AND B.BIZ_END_YMD < TO_CHAR(SYSDATE,'YYYYMMDD')

mapper.delete:
DELETE /* isry.itgcm.crtrinfo.resrce.SrvcBizMapper.deleteExcnSrvcBiz(실행서비스사업 삭제) */
  FROM SDA430 /* 실행서비스세부사업 */
 WHERE EXCN_SRVC_BIZ_CL_NO      = #{EXCN_SRVC_BIZ_CL_NO}
